import{_ as a,o as r,c as t,a0 as s}from"./chunks/framework.BTg7EidG.js";const o="/athanor-docs/screens/city-jobs.png",i="/athanor-docs/screens/city-training.png",n="/athanor-docs/screens/city-build.png",l="/athanor-docs/screens/city-research.png",y=JSON.parse('{"title":"Cities & Holdings","description":"","frontmatter":{},"headers":[],"relativePath":"guide/cities.md","filePath":"guide/cities.md"}'),h={name:"guide/cities.md"};function d(c,e,g,m,u,p){return r(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="cities-holdings" tabindex="-1">Cities &amp; Holdings <a class="header-anchor" href="#cities-holdings" aria-label="Permalink to &quot;Cities &amp; Holdings&quot;">​</a></h1><p>Tap one of your cities and the city board opens straight away — with or without a party selected on it. Cities level from 1 to 3 — each level adds job slots, a floor to the skyline, and eventually unlocks the best projects.</p><h2 id="jobs" tabindex="-1">Jobs <a class="header-anchor" href="#jobs" aria-label="Permalink to &quot;Jobs&quot;">​</a></h2><p><img src="'+o+'" alt="City jobs"></p><p>Spare <strong>Followers</strong> work the five city jobs: the <strong>Market</strong> (gold), <strong>Tavern</strong> (elixir), <strong>Temple</strong> (reagents), <strong>Magistrate</strong> (infamy) and the <strong>Farms</strong> (2 food each — the best-paying plot in the city). Infamy matters: your deeds plus your magistrates decide how many new Followers arrive every seventh day.</p><h2 id="food-farms" tabindex="-1">Food &amp; farms <a class="header-anchor" href="#food-farms" aria-label="Permalink to &quot;Food &amp; farms&quot;">​</a></h2><p>The faithful march on bread, not coin: every <strong>recruit costs 1 Follower, 40 food and 20 elixir</strong> — gold buys mercenaries, structures and training, never the faithful. Cities grow a base crop (villages a smaller one), Farm workers grow more, and for real granaries you settle <strong>farmsteads</strong>: hire a <strong>Farm Hand</strong> at any of your cities (100🪙), march them out with a party, and on held, empty ground the command bar&#39;s <strong>🌾 slot</strong> lights up to raise the farmstead. The hand settles there for good; the farmstead yields 10 food a day at full control — and like any holding of yours, its fences <strong>ward the blight</strong>. A ring of farms is both a food supply and a wall.</p><h2 id="training" tabindex="-1">Training <a class="header-anchor" href="#training" aria-label="Permalink to &quot;Training&quot;">​</a></h2><p><img src="'+i+'" alt="The training hall"></p><p>Every unit standing at the building — in a party or the garrison — can buy its next level for gold and elixir. The drillmaster only charges for what is left to learn: a soldier already three-quarters of the way to the next level pays a quarter of the list price, so battle scars are money in the bank. Training takes the day; the queue shows who&#39;s drilling. Keep a high-level veteran garrisoned and new recruits start at half their level.</p><p>Barracks train warriors, Laboratories train alchemists, Shadow Guilds train rogues; cities and Grand Athanors drill warriors. Tap any owned trainer building on the map to open its hall directly.</p><h2 id="build" tabindex="-1">Build <a class="header-anchor" href="#build" aria-label="Permalink to &quot;Build&quot;">​</a></h2><p><img src="'+n+'" alt="The build queue"></p><p>Cities can raise new structures on free land beside them — a Barracks, Laboratory or Distillery, and at city level 3 a Shadow Guild. One project at a time; a few days each.</p><h2 id="research" tabindex="-1">Research <a class="header-anchor" href="#research" aria-label="Permalink to &quot;Research&quot;">​</a></h2><p><img src="'+l+'" alt="Skill research"></p><p>The Town Hall researches hero skills, one project at a time, guild-wide once learned. Class skills are innate; a <strong>level‑2 city</strong> unlocks the deeper studies (<em>Shield Wall</em>, <em>Plunder</em>, <em>Field Mending</em>) and a <strong>level‑3 city</strong> the masterworks (<em>Warcry</em>, <em>Overwhelm</em>, <em>Quicksilver March</em>). Once researched, assign the skill on any matching hero&#39;s sheet. The full tree lives in <a href="/athanor-docs/guide/skills.html">Skills &amp; Research</a>.</p><h2 id="defense" tabindex="-1">Defense <a class="header-anchor" href="#defense" aria-label="Permalink to &quot;Defense&quot;">​</a></h2><p>If a visible enemy prowls within sight of an undefended holding, the game warns you and offers an <strong>emergency muster</strong> — recruits or mercenaries straight onto the walls. The locate button&#39;s jump list shows every city, flagging any whose walls stand empty.</p>',19)])])}const b=a(h,[["render",d]]);export{y as __pageData,b as default};
